const envelope = $input.first().json;
const raw = envelope.body ?? envelope;
const payload = raw.payload ?? {};
const event = payload.event;
if (!event?.id || !event.memberAlias || !event.startedAt) return [{ json: { ok:false, error:'invalid_event_contract', message:'A complete synthetic wearable event is required.' } }];
const appointments = Array.isArray(payload.appointments) ? payload.appointments : [];
const workouts = Array.isArray(payload.workouts) ? payload.workouts : [];
const start = new Date(event.startedAt).getTime();
const end = start + Number(event.durationMinutes) * 60000;
const overlap = (otherStart, minutes) => { const a = new Date(otherStart).getTime(); const b = a + Number(minutes || event.durationMinutes) * 60000; return Math.max(0, Math.min(end,b)-Math.max(start,a)) / Math.max(1,end-start); };
const nearbyAppointment = appointments.filter(a => a.memberAlias === event.memberAlias).map(a => ({...a, overlap: overlap(a.startsAt,a.durationMinutes)})).sort((a,b)=>b.overlap-a.overlap)[0];
const nearbyWorkout = workouts.filter(w => w.memberAlias === event.memberAlias && String(w.activity).toLowerCase() === String(event.activity).toLowerCase()).map(w => ({...w, overlap: overlap(w.startedAt,event.durationMinutes)})).sort((a,b)=>b.overlap-a.overlap)[0];
let outcome='save', confidence=94, overlapPercent=0, linkedRecordId;
if (nearbyWorkout && nearbyWorkout.overlap >= .7) { outcome='review'; confidence=98; overlapPercent=Math.round(nearbyWorkout.overlap*100); linkedRecordId=nearbyWorkout.id; } else if (nearbyAppointment && nearbyAppointment.overlap >= .7) { outcome='link'; confidence=96; overlapPercent=Math.round(nearbyAppointment.overlap*100); linkedRecordId=nearbyAppointment.id; }
const explanation = outcome === 'save' ? `No matching session or recorded activity overlaps ${event.activity}. ActiveFlow can save the verified wearable event as a new record.` : outcome === 'link' ? `The event overlaps an existing trainer session by ${overlapPercent}%. ActiveFlow links the signal to that session instead of creating a duplicate workout.` : `A matching activity already overlaps by ${overlapPercent}%. ActiveFlow stops automatic creation and asks a person to review the possible duplicate.`;
const requestId=String(raw.requestId ?? `reconcile-${Date.now()}`);
return [{json:{ok:true,requestId,correlationId:`af_reconciliation_${requestId}`.replace(/[^a-zA-Z0-9_-]/g,'_'),proposal:{scenario:'wearable_reconciliation',explanation,businessRules:['synthetic event contract validated','time-window overlap policy','duplicate prevention before writes','human approval required','persistent audit trail'],proposedAction:{eventId:event.id,outcome,confidence,overlapPercent,linkedRecordId}},audit:{externalWrites:0,companySystemsContacted:0},portfolioSafety:{syntheticData:true,proprietaryCode:false,companyEndpoints:false}}}];
